  it("returns only quizzes for the authenticated shop", async () => {
    // Create quiz for different shop (should not be returned)
    await prisma.quiz.create({
      data: { shop: "other-shop.myshopify.com", title: "Other Quiz", slug: "other", status: "DRAFT" },
